update public.cms_sections set data='{"eyebrow": "Contact LMI", "heading": "Have a Transportation Requirement in Mind?", "description": "Tell us what you need to move, where it needs to go and any important operating requirements. Our team will review it and help determine the right transportation approach.", "action": {"label": "Get a Quote", "href": "#quote-form"}, "image": "/contact-us/section-1-main-image.png", "imageAlt": "LMI truck and team at a terminal", "imagePlaceholder": "[Photo: LMI truck and team at a terminal]"}'::jsonb,revision=70 where page_id='contact-us' and key='sectionOne';
update public.cms_sections set data='{"eyebrow": "From the road", "heading": "Insights & Case Studies on Road Transportation in Pakistan", "description": "Real movements and practical guidance from LMI’s decades of road transportation in Pakistan.", "action": {"label": "Discuss Your Requirement", "path": "/contact-us"}, "image": "/insights/section-1-main-image.png", "imageAlt": "LMI trucks at a terminal", "imagePlaceholder": "[Photo: LMI trucks at a terminal]"}'::jsonb,revision=70 where page_id='insights' and key='sectionOne';
update public.cms_sections set data='{"eyebrow": "From our leadership", "quote": "“Our customers trust us with cargo that cannot afford to be late or unsafe. That is why every journey starts with the right vehicle, a trained driver and safety as a first priority. It is how we have built long relationships, and how we intend to keep them.”", "name": "Brig. (R) Shahid Mahmood", "role": "CEO, Logistics Management International", "image": "/insights/section-3-main-image.png", "imagePlaceholder": "[Portrait: Brig. (R) Shahid Mahmood]"}'::jsonb,revision=70 where page_id='insights' and key='sectionThree';
update public.cms_sections set data='{"eyebrow": "Case studies", "heading": "Transportation in Practice", "cards": [{"eyebrow": "Case study 01", "heading": "Fertilizer lifted from Karachi’s ports", "industry": "Industry: Chemicals & Fertilizer", "service": "Service: Road Freight", "description": "Urea moved from seaports to destinations across Pakistan for a major fertilizer producer.", "note": "[Confirm: challenge, approach and verified result]", "image": "/insights/section-2-image-1.png", "imagePlaceholder": "[Photo: case study 1]", "label": "Read case study", "path": "#case-study-approach"}, {"eyebrow": "Case study 02", "heading": "Supporting a national highway project (1999)", "industry": "Industry: Construction & Engineering", "service": "Service: Project transport", "description": "Transport contractor to an international engineering contractor on a highway contract in D.I. Khan.", "note": "[Confirm: challenge, approach and verified result]", "image": "/insights/section-2-image-2.png", "imagePlaceholder": "[Photo: case study 2]", "label": "Read case study", "path": "#case-study-approach"}, {"eyebrow": "Case study 03", "heading": "Bitumen from Karachi to Jhelum and Kuzdar (1992)", "industry": "Industry: Construction & Engineering", "service": "Service: Petroleum Transportation", "description": "Bitumen moved from a Karachi refinery to road-construction sites for an international contractor.", "note": "[Confirm: challenge, approach and verified result]", "image": "/insights/section-2-image-3.png", "imagePlaceholder": "[Photo: case study 3]", "label": "Read case study", "path": "#case-study-approach"}]}'::jsonb,revision=70 where page_id='insights' and key='sectionTwo';
